prestige:
#set page(paper: "a4", margin: 0pt)
#set text(font: "Liberation Serif", size: 10pt, fill: rgb("{{textColorDark}}"))
#let themeColor = rgb("{{themeColor}}")

#block(width: 100%, height: 100%, fill: rgb("#f9f9f9"))[
  #grid(
    columns: (35%, 65%),
    rows: (100%),
    block(inset: 20pt)[
      #align(center + horizon)[
        #block(width: 70pt, height: 70pt, stroke: 2pt + themeColor)[
          #align(center + horizon)[#text(size: 22pt, weight: "bold", fill: themeColor)[{{initials}}]]
        ]
        #v(10pt)
        #text(size: 18pt, weight: "bold")[{{fullName}}]
        #v(-2pt)
        #text(size: 10pt)[{{title}}]
      ]
    ],
    block(inset: 25pt, stroke: (left: 1pt + rgb("#ddd")))[
      {{sectionsTypst}}
    ]
  )
]

sleek-cv:
#set page(paper: "a4", margin: 0pt)
#set text(font: "Liberation Sans", size: 10pt, fill: rgb("{{textColorDark}}"))
#let themeColor = rgb("{{themeColor}}")

#block(width: 100%, fill: rgb("#212529"), inset: (x: 25pt, y: 25pt))[
  #set text(fill: white)
  #grid(columns: (1fr, auto), [
    #text(size: 24pt, weight: "bold")[{{fullName}}]
    #v(-2pt)
    #text(size: 11pt, fill: themeColor)[{{title}}]
  ], [
    #text(size: 8.5pt)[{{email}} \ {{phone}}]
  ])
]
#block(inset: 25pt)[
  {{sectionsTypst}}
]

modern-pro:
#set page(paper: "a4", margin: 0pt)
#set text(font: "Liberation Sans", size: 9.5pt, fill: rgb("{{textColorDark}}"))
#let themeColor = rgb("{{themeColor}}")

#block(width: 100%, fill: themeColor, inset: (x: 25pt, y: 20pt))[
  #set text(fill: white)
  #grid(columns: (1fr, auto), [
    #text(size: 24pt, weight: "bold")[{{fullName}}]
    #v(-2pt)
    #text(size: 12pt, weight: "medium")[{{title}}]
  ], [
    #text(size: 8.5pt)[{{email}} \ {{phone}} \ {{website}}]
  ])
]
#block(inset: 25pt)[
  #grid(columns: (2.3fr, 1fr), gutter: 20pt, [
    {{sectionsTypst}}
  ], [
    #text(weight: "bold", size: 10pt, fill: themeColor)[SKILLS]
    #v(4pt)
    {{skillsListTypst}}
  ])
]
